    public Object parseTransaction(Object transaction, Object... optionalArgs)
    {
        //
        // fetchDeposits
        //     {
        //         "createTime": 1760368656,
        //         "txHash": "03fe3244d89e794586222413c61779380da9e9fe5baaa253c38d01a4199a3499",
        //         "chainName": "TRC20",
        //         "amount": "149",
        //         "coin": "USDT",
        //         "status": "succeed"
        //     }
        //
        Object currency = Helpers.getArg(optionalArgs, 0, null);
        Object txid = this.safeString(transaction, "txHash");
        Object currencyId = this.safeString(transaction, "coin");
        Object code = this.safeCurrencyCode(currencyId, currency);
        Object amount = this.safeNumber(transaction, "amount");
        Object timestamp = this.safeTimestamp(transaction, "createTime");
        Object networkId = this.safeString(transaction, "chainName");
        Object network = this.networkIdToCode(networkId, code);
        Object status = this.parseTransactionStatus(this.safeString(transaction, "status"));
        return new java.util.HashMap<String, Object>() {{
            put( "info", transaction );
            put( "id", null );
            put( "currency", code );
            put( "amount", amount );
            put( "network", network );
            put( "addressFrom", null );
            put( "addressTo", null );
            put( "address", Deepcoin.this.safeString(transaction, "address") );
            put( "tagFrom", null );
            put( "tagTo", null );
            put( "tag", null );
            put( "status", status );
            put( "type", null );
            put( "updated", null );
            put( "txid", txid );
            put( "timestamp", timestamp );
            put( "datetime", Deepcoin.this.iso8601(timestamp) );
            put( "internal", null );
            put( "comment", null );
            put( "fee", new java.util.HashMap<String, Object>() {{
                put( "currency", null );
                put( "cost", null );
            }} );
        }};
    }

    public Object parseTransactionStatus(Object status)
    {
        Object statuses = new java.util.HashMap<String, Object>() {{
            put( "confirming", "pending" );
            put( "succeed", "ok" );
        }};
        return this.safeString(statuses, ((String)status), status);
    }

